<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$q=trim($_GET['q']??'');$users=[];$events=[];if($q!==''){$like='%'.$q.'%';$s=$pdo->prepare('SELECT id,full_name,email,profile_picture FROM users WHERE (full_name LIKE ? OR email LIKE ?) AND id<>? ORDER BY full_name LIMIT 30');$s->execute([$like,$like,$_SESSION['user_id']]);$users=$s->fetchAll();$s=$pdo->prepare('SELECT e.id,e.title,e.description,e.location,e.event_date,u.full_name AS creator_name FROM events e JOIN users u ON u.id=e.user_id WHERE e.title LIKE ? OR e.description LIKE ? OR e.location LIKE ? ORDER BY e.event_date ASC LIMIT 50');$s->execute([$like,$like,$like]);$events=$s->fetchAll();}$page_title='Search';require __DIR__.'/includes/header.php'; ?>
<section class="panel"><h1>Search people and events</h1><form method="get" class="search-form" data-live-search><input type="search" name="q" value="<?= e($q) ?>" placeholder="Search by name, email, event or location…" aria-label="Search people and events"><button class="button primary" type="submit">Search</button></form><p class="muted">Results update as you type.</p></section><?php if($q!==''): ?><div class="results-grid"><section class="panel"><h2>People (<?= count($users) ?>)</h2><?php if(!$users): ?><p class="muted">No people found.</p><?php endif; ?><?php foreach($users as $u): ?><article class="person-row"><img src="<?= avatar($u) ?>" alt=""><div><strong><?= e($u['full_name']) ?></strong><p><?= e($u['email']) ?></p><a href="user_profile.php?id=<?= (int)$u['id'] ?>">View profile</a> · <a href="conversation.php?user_id=<?= (int)$u['id'] ?>">Message</a></div></article><?php endforeach; ?></section><section class="panel"><h2>Events (<?= count($events) ?>)</h2><?php if(!$events): ?><p class="muted">No events found.</p><?php endif; ?><?php foreach($events as $ev): ?><article class="event-row"><div><h3><?= e($ev['title']) ?></h3><p><?= e($ev['description']) ?></p><small><?= e(date('d M Y · H:i',strtotime($ev['event_date']))) ?> · <?= e($ev['location']) ?></small><p class="muted">Created by <?= e($ev['creator_name']) ?></p></div></article><?php endforeach; ?></section></div><?php endif; ?><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[data-live-search]');if(f){let t;f.querySelector('input').addEventListener('input',()=>{clearTimeout(t);t=setTimeout(()=>f.requestSubmit(),450)})}});</script><?php require __DIR__.'/includes/footer.php'; ?>